declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

// 中身の分からない値を受け取り、正体を確かめてから説明の文字列を返す
function describe(data: unknown): string {
  // ここを書く
  return "";
}

const lines = input.split("\n").filter((l) => l !== "");
for (const line of lines) {
  const data: unknown = JSON.parse(line);
  console.log(describe(data));
}

quiz.answer:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

function describe(data: unknown): string {
  if (typeof data === "string") {
    return "文字列: " + data;
  }
  if (typeof data === "number") {
    return "数値: " + data.toFixed(1);
  }
  if (typeof data === "boolean") {
    return "真偽値: " + data;
  }
  if (data === null) {
    return "null";
  }
  if (Array.isArray(data)) {
    return "配列: 長さ" + data.length;
  }
  if (typeof data === "object") {
    return "オブジェクト: キー" + Object.keys(data).length + "個";
  }
  return "その他";
}

const lines = input.split("\n").filter((l) => l !== "");
for (const line of lines) {
  const data: unknown = JSON.parse(line);
  console.log(describe(data));
}

quiz.setup:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

// data が「id が数値のオブジェクト」なら id を返す。それ以外は undefined
function getId(data: unknown): number | undefined {
  // ここを書く(as や any は使わない)
  return undefined;
}

const lines = input.split("\n").filter((l) => l !== "");
for (const line of lines) {
  const id = getId(JSON.parse(line));
  console.log(id === undefined ? "id が不正" : "id=" + (id + 1) + " (次のID)");
}

quiz.answer:
declare function require(name: string): any;
const input: string = require("fs").readFileSync(0, "utf8");

function getId(data: unknown): number | undefined {
  if (typeof data === "object" && data !== null && "id" in data && typeof data.id === "number") {
    return data.id;
  }
  return undefined;
}

const lines = input.split("\n").filter((l) => l !== "");
for (const line of lines) {
  const id = getId(JSON.parse(line));
  console.log(id === undefined ? "id が不正" : "id=" + (id + 1) + " (次のID)");
}
